package com.yuegang.zhihui.product.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.product.application.*;import com.yuegang.zhihui.product.security.*;import jakarta.servlet.http.*;import jakarta.validation.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController public final class ProductAdministrationController{private final ProductAdministrationService service;private final ProductCacheService cache;private final ProductAdminVerifier admin;public ProductAdministrationController(ProductAdministrationService s,ProductCacheService c,ProductAdminVerifier a){service=s;cache=c;admin=a;}@PutMapping("/api/v1/admin/products/{sku}")ApiResponse<ProductView>update(@PathVariable String sku,@Valid @RequestBody UpdateProductRequest b,HttpServletRequest r){admin.verify(r);ProductView v=service.update(sku,b);cache.invalidate(sku);return ok(v,r);}@PostMapping("/api/v1/admin/products/{sku}/batches")ApiResponse<ProductBatchView>batch(@PathVariable String sku,@Valid @RequestBody SaveProductBatchRequest b,HttpServletRequest r){admin.verify(r);ProductBatchView v=service.batch(sku,b);cache.invalidate(sku);return ok(v,r);}@GetMapping("/api/v1/products/{sku}/batches")ApiResponse<List<ProductBatchView>>batches(@PathVariable String sku,HttpServletRequest r){return ok(service.batches(sku),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
